function ionicPairReachProfileForFreshSites(rawFreshSites) {
  const freshSites = uniqueFreshSites(rawFreshSites);
  if (!formalChargeTarget?.available || !freshSites.length) return { available: false,
    reason: "complete supplied-charge candidate unavailable", samples: [] };
  const currentSites = atoms.map((atom) => ({ position: atom.p.toArray(),
    charge: suppliedFormalChargeForToken(atom.species) }));
  const addedSites = freshSites.map((site) => ({ position: site.p.toArray(),
    charge: suppliedFormalChargeForToken(site.species) }));
  if (![...currentSites, ...addedSites].every((site) => Number.isFinite(site.charge))) {
    return { available: false, reason: "candidate charge unresolved", samples: [] };
  }
  return incrementalIonicPairReachProfile(currentSites, addedSites, {
    nearestNeighborScale: referenceSpacing,
    reaches: [2, 4, 8, "global"],
  });
}

function bondValenceLabel() {
  return bondValenceMode === "satisfy" ? "scalar valence-sum satisfaction"
    : bondValenceMode === "vector" ? "bond-valence vector balance"
      : bondValenceMode === "combined" ? "scalar + vector bond-valence satisfaction"
        : "bond-valence diagnostic";
}

function activeBondValenceWeight() {
  return bondValenceMode === "none" || !formalChargeTarget?.available ? 0 : bondValenceWeight;
}

function bondValenceElementToken(token) {
  const match = String(token).match(/^([A-Z][a-z]?)(?:\^[+-]\d+(?:\.\d+)?)?$/);
  return match?.[1] || null;
}

function bondValenceForFreshSites(rawFreshSites, { recordWork = true } = {}) {
  const freshSites = uniqueFreshSites(rawFreshSites);
  const chargesResolved = Boolean(formalChargeTarget?.available && freshSites.length
    && freshSites.every((site) => bondValenceElementToken(site.species)
      && Number.isFinite(suppliedFormalChargeForToken(site.species))
      && Math.abs(suppliedFormalChargeForToken(site.species)) > 1e-12));
  if (!chargesResolved) return { available: false, enabled: false, mode: bondValenceMode,
    label: bondValenceLabel(), score: 0, rawScore: 0, affectedSites: [], distanceEvaluations: 0,
    reason: !formalChargeTarget?.available ? "complete supplied oxidation-state channel unavailable"
      : !freshSites.length ? "candidate adds no sites" : "candidate oxidation state unresolved",
    targetUsed: false, candidateGeometryChanged: false, hardAdmissionChanged: false,
    oxidationStatesInferred: false, bondEnergyInferred: false, physicalTimeIntegrated: false };
  const scenePerAngstrom = referenceSpacing / Math.max(referenceSpacingA, 1e-12);
  const cutoff = MAXIMUM_BOND_VALENCE_DISTANCE * scenePerAngstrom;
  const localAtoms = new Set();
  freshSites.forEach((site) => nearbyAtoms(site.p, cutoff).forEach((atom) => localAtoms.add(atom)));
  [...localAtoms].forEach((atom) => nearbyAtoms(atom.p, cutoff).forEach((neighbor) => localAtoms.add(neighbor)));
  const toPhysical = (site) => ({ species: bondValenceElementToken(site.species),
    charge: suppliedFormalChargeForToken(site.species),
    position: site.p.toArray().map((value) => value / scenePerAngstrom) });
  const result = incrementalBondValenceSatisfaction([...localAtoms].map(toPhysical), freshSites.map(toPhysical));
  if (recordWork) {
    bondValenceEvaluations++;
    bondValenceDistanceEvaluations += result.distanceEvaluations || 0;
  }
  const selectedScore = bondValenceMode === "vector" ? result.vectorScore
    : bondValenceMode === "combined" ? result.combinedScore : result.scalarScore;
  return { ...result, mode: bondValenceMode, label: bondValenceLabel(),
    enabled: bondValenceMode !== "none", rawScore: selectedScore || 0,
    score: bondValenceMode === "none" ? 0 : selectedScore || 0,
    localCurrentSites: localAtoms.size,
    physicalScaleAngstromPerSceneUnit: referenceSpacingA / Math.max(referenceSpacing, 1e-12) };
}

function structuralBondValenceSnapshot(maximumCenters = 96) {
  const eligibleIndices = formalChargeTarget?.available ? atoms.map((atom, index) =>
    bondValenceElementToken(atom.species)
      && Number.isFinite(suppliedFormalChargeForToken(atom.species))
      && Math.abs(suppliedFormalChargeForToken(atom.species)) > 1e-12 ? index : null)
    .filter(Number.isInteger) : [];
  if (!eligibleIndices.length) return { available: false,
    reason: "complete exact oxidation-state channel unavailable", sampledCenters: 0,
    resolvedCenters: 0, maximumCenters, targetUsed: false, analysisOnly: true };
  const sampledIndices = radiallyStratifiedIndices(atoms, eligibleIndices, maximumCenters);
  const scenePerAngstrom = referenceSpacing / Math.max(referenceSpacingA, 1e-12);
  const cutoffSceneUnits = MAXIMUM_BOND_VALENCE_DISTANCE * scenePerAngstrom;
  const toPhysical = (atom) => ({ species: bondValenceElementToken(atom.species),
    charge: suppliedFormalChargeForToken(atom.species),
    position: atom.p.toArray().map((value) => value / scenePerAngstrom) });
  const neighborhoods = sampledIndices.map((centerIndex) => {
    const center = atoms[centerIndex];
    const neighbors = nearbyAtoms(center.p, cutoffSceneUnits).filter((atom) => atom !== center
      && bondValenceElementToken(atom.species)
      && Number.isFinite(suppliedFormalChargeForToken(atom.species))
      && Math.abs(suppliedFormalChargeForToken(atom.species)) > 1e-12);
    return [center, ...neighbors].map(toPhysical);
  });
  const summary = bondValenceStateSummary(neighborhoods);
  return { ...summary,
    sampledCenters: sampledIndices.length,
    unresolvedCenters: sampledIndices.length - summary.resolvedCenters, maximumCenters,
    cutoffAngstrom: MAXIMUM_BOND_VALENCE_DISTANCE,
    sampling: "up to 96 radially stratified centers; each center uses its complete finite neighbor halo within the largest checked parameter cutoff",
    suppliedOxidationStatesOnly: true, oxidationStatesInferred: false,
    finiteObservationNoPeriodicImages: true, coordinateFrameUsed: false,
    translationInvariant: true, properRotationInvariant: true, uniformScaleInvariant: false,
    physicalAngstromScaleRequired: true, sphericalIonHypothesisOnly: true,
    anisotropyCanBePhysical: true, candidateRankingChanged: false,
    candidateGeometryChanged: false, hardAdmissionChanged: false,
    analysisOnly: true, targetUsed: false, physicalTimeIntegrated: false };
}

function currentBondValenceSpatialField(maximumCenters = 320) {
  if (bondValenceMapMode === "none") return { available: false, mode: "none",
    reason: "3D coordination-defect map disabled", maximumCenters, targetUsed: false };
  const eligibleIndices = formalChargeTarget?.available ? atoms.map((atom, index) =>
    bondValenceElementToken(atom.species)
      && Number.isFinite(suppliedFormalChargeForToken(atom.species))
      && Math.abs(suppliedFormalChargeForToken(atom.species)) > 1e-12 ? index : null)
    .filter(Number.isInteger) : [];
  if (!eligibleIndices.length) return { available: false, mode: bondValenceMapMode,
    reason: "complete supplied oxidation states required", maximumCenters, targetUsed: false };
  const sampledIndices = radiallyStratifiedIndices(atoms, eligibleIndices, maximumCenters);
  const scenePerAngstrom = referenceSpacing / Math.max(referenceSpacingA, 1e-12);
  const cutoffSceneUnits = MAXIMUM_BOND_VALENCE_DISTANCE * scenePerAngstrom;
  const toPhysical = (atom) => ({ species: bondValenceElementToken(atom.species),
    charge: suppliedFormalChargeForToken(atom.species),
    position: atom.p.toArray().map((value) => value / scenePerAngstrom) });
  let distanceEvaluations = 0; let contextSitePresentations = 0;
  const records = sampledIndices.map((centerIndex) => {
    const atom = atoms[centerIndex];
    const neighbors = nearbyAtoms(atom.p, cutoffSceneUnits).filter((neighbor) => neighbor !== atom
      && bondValenceElementToken(neighbor.species)
      && Number.isFinite(suppliedFormalChargeForToken(neighbor.species))
      && Math.abs(suppliedFormalChargeForToken(neighbor.species)) > 1e-12);
    const local = bondValenceSums([atom, ...neighbors].map(toPhysical));
    distanceEvaluations += local.distanceEvaluations; contextSitePresentations += 1 + neighbors.length;
    const center = local.sites[0];
    return center?.resolved ? { atom, scalarResidual: center.residual,
      absoluteScalarResidual: center.absoluteResidual, vectorSum: center.vectorSum,
      vectorMagnitude: center.vectorMagnitude, normalizedVectorImbalance: center.normalizedVectorImbalance,
      bondValenceSum: center.sum, targetValence: center.target, bondCount: center.bondCount } : null;
  }).filter(Boolean);
  const percentile90 = (values) => {
    if (!values.length) return 0;
    const sorted = [...values].sort((first, second) => first - second);
    return sorted[Math.min(sorted.length - 1, Math.floor(.9 * sorted.length))];
  };
  const scalarScale = Math.max(.1, percentile90(records.map((record) => record.absoluteScalarResidual)));
  const vectorScale = Math.max(.1, percentile90(records.map((record) => record.vectorMagnitude)));
  return { available: records.length > 0, mode: bondValenceMapMode,
    reason: records.length ? null : "no sampled center has a checked ion-pair neighbor",
    sampledCenters: sampledIndices.length, resolvedCenters: records.length,
    unresolvedCenters: sampledIndices.length - records.length, maximumCenters, records,
    scalarScale, vectorScale, cutoffAngstrom: MAXIMUM_BOND_VALENCE_DISTANCE,
    distanceEvaluations, contextSitePresentations,
    sampling: "up to 320 radially stratified centers with complete finite checked-parameter neighbor halos",
    suppliedOxidationStatesOnly: true, finiteObservationNoPeriodicImages: true,
    elementColorsPreserved: true, candidateRankingChanged: false,
    candidateGeometryChanged: false, hardAdmissionChanged: false,
    targetUsed: false, physicalTimeIntegrated: false };
}

function bondValenceSpatialFieldReceipt() {
  const field = currentBondValenceSpatialField();
  return { role: "current-structure spatial microscope for local scalar and directional bond-valence imbalance",
    mode: field.mode, available: field.available, reason: field.reason,
    sampledCenters: field.sampledCenters || 0, resolvedCenters: field.resolvedCenters || 0,
    maximumCenters: field.maximumCenters, scalarDisplayScale: receiptRound(field.scalarScale),
    vectorDisplayScale: receiptRound(field.vectorScale), cutoffAngstrom: field.cutoffAngstrom,
    contextSitePresentations: field.contextSitePresentations || 0,
    distanceEvaluations: field.distanceEvaluations || 0,
    sampling: field.sampling || "map disabled", elementColorsPreserved: true,
    displayOnly: true, vectorArrowsAreForces: false, energyInferred: false,
    candidateRankingChanged: false, candidateGeometryChanged: false,
    hardAdmissionChanged: false, targetUsed: false, physicalTimeIntegrated: false };
}

function renderBondValenceMapExtremes(field) {
  if (!bondValenceMapExtremes) return;
  bondValenceMapExtremes.replaceChildren();
  if (!field?.available) return;
  const magnitude = (record) => bondValenceMapMode === "scalar"
    ? record.absoluteScalarResidual : record.vectorMagnitude;
  [...field.records].sort((first, second) => magnitude(second) - magnitude(first)
    || String(first.atom.id).localeCompare(String(second.atom.id))).slice(0, 8).forEach((record) => {
    const button = document.createElement("button"); button.type = "button";
    button.classList.toggle("active", record.atom.id === selectedBondValenceAtomId);
    button.setAttribute("aria-pressed", String(record.atom.id === selectedBondValenceAtomId));
    const label = document.createElement("strong");
    label.textContent = `${record.atom.species} · ${record.atom.id}`;
    const value = document.createElement("span");
    value.textContent = bondValenceMapMode === "scalar"
      ? `Δs ${record.scalarResidual >= 0 ? "+" : ""}${record.scalarResidual.toFixed(2)} v.u.`
      : `|V| ${record.vectorMagnitude.toFixed(2)} v.u.`;
    button.append(label, value);
    button.addEventListener("click", () => {
      selectedBondValenceAtomId = record.atom.id;
      controls.target.copy(record.atom.p); controls.update(); rebuildWorld();
    });
    bondValenceMapExtremes.append(button);
  });
}

function currentCollinearSpinGeometry() {
  const spinAtoms = atoms.filter((atom) => Number.isFinite(atom.calculationSpin));
  const signature = `${referenceSpacingA.toFixed(8)}|${atoms.length}|${spinAtoms.map((atom) =>
    `${atom.id}:${atom.calculationSpin}`).join("|")}`;
  if (spinGeometryCache?.signature === signature) return spinGeometryCache.audit;
  const sceneToAngstrom = referenceSpacingA / Math.max(referenceSpacing, 1e-12);
  const atomById = new Map(atoms.map((atom) => [atom.id, atom]));
  const audit = analyzeCollinearSpinGeometry(atoms.map((atom) => ({
    species: atom.displaySpecies || atom.species,
    position: atom.p.toArray().map((value) => value * sceneToAngstrom),
    spin: atom.calculationSpin,
    sourceIndex: atom.id,
  })), { maximumReach: 5 * referenceSpacingA, binCount: 12 });
  audit.records = audit.available ? audit.localRecords.map((record) => ({ ...record, atom: atomById.get(record.sourceIndex) }))
    .filter((record) => record.atom) : [];
  audit.displayMode = spinMapMode;
  audit.elementColorsPreserved = true;
  audit.displayOnly = true;
  spinGeometryCache = { signature, audit };
  return audit;
}

function referenceCollinearSpinGeometry() {
  return analyzeCollinearSpinGeometry(referenceAtoms.map((atom, index) => ({
    species: atom.displaySpecies || atom.species,
    position: atom.pA?.toArray() || atom.p.toArray().map((value) =>
      value * referenceSpacingA / Math.max(referenceSpacing, 1e-12)),
    spin: atom.calculationSpin,
    sourceIndex: Number.isInteger(atom.sourceIndex) ? atom.sourceIndex : index,
  })), { maximumReach: 5 * referenceSpacingA, binCount: 12 });
}

function renderSpinMapExtremes(audit) {
  spinMapExtremes.replaceChildren();
  if (!audit.available || spinMapMode === "none") return;
  const magnitude = (record) => spinMapMode === "polarity" ? Math.abs(record.spin)
    : Math.abs(record.localCorrelation ?? 0);
  [...audit.records].sort((first, second) => magnitude(second) - magnitude(first)
    || String(first.atom.id).localeCompare(String(second.atom.id))).slice(0, 8).forEach((record) => {
    const button = document.createElement("button"); button.type = "button";
    button.classList.toggle("active", record.atom.id === selectedSpinAtomId);
    button.setAttribute("aria-pressed", String(record.atom.id === selectedSpinAtomId));
    const label = document.createElement("strong"); label.textContent = `${record.atom.species} · ${record.atom.id}`;
    const value = document.createElement("span");
    value.textContent = spinMapMode === "polarity" ? `s ${record.spin >= 0 ? "+" : ""}${record.spin.toFixed(3)}`
      : `Cᵢ ${record.localCorrelation === null ? "—" : record.localCorrelation.toFixed(3)}`;
    button.append(label, value);
    button.addEventListener("click", () => {
      selectedSpinAtomId = record.atom.id;
      controls.target.copy(record.atom.p); controls.update(); rebuildWorld();
    });
    spinMapExtremes.append(button);
  });
}

function renderCollinearSpinGeometry() {
  const audit = currentCollinearSpinGeometry();
  spinCorrelationPlot.replaceChildren(); spinGeometryDetail.replaceChildren();
  spinMapSelect.disabled = !audit.available;
  if (!audit.available) {
    spinGeometryState.textContent = "explicit atomic spins unavailable";
    spinMapState.textContent = spinMapMode === "none" ? "map off" : audit.reason;
    renderSpinMapExtremes(audit); return;
  }
  const namespace = "http://www.w3.org/2000/svg";
  const make = (name, attributes = {}) => {
    const element = document.createElementNS(namespace, name);
    Object.entries(attributes).forEach(([key, value]) => element.setAttribute(key, String(value)));
    return element;
  };
  const left = 25; const top = 10; const width = 203; const height = 78;
  const px = (value) => left + width * value / Math.max(audit.maximumReach, 1e-12);
  const py = (value) => top + height * (.5 - .5 * Math.max(-1, Math.min(1, value)));
  spinCorrelationPlot.append(make("rect", { x: left, y: top, width, height, class: "plot-area" }),
    make("line", { x1: left, y1: py(0), x2: left + width, y2: py(0), class: "axis" }));
  const samples = audit.radialCorrelation.filter((bin) => bin.correlation !== null)
    .map((bin) => ({ ...bin, center: .5 * (bin.minimumDistance + bin.maximumDistance) }));
  if (samples.length) spinCorrelationPlot.append(make("path", { class: "curve",
    d: samples.map((sample, index) => `${index ? "L" : "M"}${px(sample.center)},${py(sample.correlation)}`).join(" ") }));
  samples.forEach((sample) => {
    const point = make("circle", { cx: px(sample.center), cy: py(sample.correlation), r: 2.4, class: "sample" });
    const title = make("title"); title.textContent = `${sample.minimumDistance.toFixed(2)}–${sample.maximumDistance.toFixed(2)} Å · C ${sample.correlation.toFixed(3)} · ${sample.pairCount} pairs`;
    point.append(title); spinCorrelationPlot.append(point);
  });
  const xLabel = make("text", { x: left + width, y: 106, class: "axis-label", "text-anchor": "end" });
  xLabel.textContent = `separation r (Å) →`;
  const yLabel = make("text", { x: 7, y: top + height / 2, class: "axis-label", "text-anchor": "middle",
    transform: `rotate(-90 7 ${top + height / 2})` });
  yLabel.textContent = "weighted C(r)"; spinCorrelationPlot.append(xLabel, yLabel);
  const heading = document.createElement("strong");
  heading.textContent = `${audit.suppliedSites}/${audit.inputSites} displayed sites carry explicit scalar spins`;
  const populations = document.createElement("span");
  populations.textContent = `${audit.positiveSites} positive · ${audit.negativeSites} negative · ${audit.nearZeroSites} near zero · normalized signed sum ${audit.netPolarization >= 0 ? "+" : ""}${audit.netPolarization.toFixed(3)}`;
  const pairs = document.createElement("span");
  pairs.textContent = `${audit.checkedPairs.toLocaleString()} finite-crop pairs through ${audit.maximumReach.toFixed(2)} Å · weighted pair correlation ${audit.weightedPairCorrelation === null ? "—" : audit.weightedPairCorrelation.toFixed(3)}`;
  const caveat = document.createElement("span");
  caveat.textContent = "Archive scalar sign/magnitude preserved; no quantization axis, vector moment, periodic magnetic sum, exchange coupling, energy, temperature, or growth score inferred.";
  const link = document.createElement("a"); link.href = COLLINEAR_SPIN_PROVENANCE.source;
  link.target = "_blank"; link.rel = "noreferrer"; link.textContent = "NOMAD Charges.spins schema ↗";
  spinGeometryDetail.append(heading, populations, pairs, caveat, link);
  spinGeometryState.textContent = `${audit.suppliedSites} scalar spins · ${(100 * audit.coverage).toFixed(0)}% displayed-site coverage`;
  spinMapState.textContent = spinMapMode === "none" ? "map off"
    : spinMapMode === "polarity" ? `|s|max ${audit.maximumAbsoluteSpin.toFixed(3)} · archive-native units`
      : `local Cᵢ over R=${audit.maximumReach.toFixed(2)} Å`;
  renderSpinMapExtremes(audit);
}

function batchRetainsNovelSites(entries) {
  if (!reconstructionCertified && replayIndex < referenceCount()) {
    const owners = new Map();
    entries.forEach((entry) => entry.evaluation.freshReferenceIndices.forEach((referenceIndex) =>
      owners.set(referenceIndex, (owners.get(referenceIndex) || 0) + 1)));
    return entries.every((entry) => entry.evaluation.freshReferenceIndices.some((referenceIndex) =>
      owners.get(referenceIndex) === 1));
  }
  return entries.every((entry, index) => entry.evaluation.fresh.some((site) => !entries.some((other, otherIndex) =>
    otherIndex !== index && other.sites.some((otherSite) => otherSite.species === site.species
      && otherSite.p.distanceTo(site.p) <= COMMUTING_SITE_TOLERANCE))));
}

function rejectionIsOrderInvariant(candidate, evaluation) {
  const markingRejected = policySelect.value === "marked" && !candidate.markingAccepted;
  return evaluation.conflicts > 0 || evaluation.boundaryFailures > 0
    || evaluation.coordinationOverflows?.length > 0 || evaluation.angularViolations?.length > 0
    || evaluation.fresh.length === 0 || !evaluation.feedstockSupply?.admitted || markingRejected;
}

function commutingFrontierBatch() {
  const audit = reconstructionCertified
    ? { matched: referenceCount(), missing: 0, duplicateAtoms: 0, extraneousAtoms: 0 }
    : referenceCoverageAudit();
  // Candidate enumeration is frozen before this ranking. Geometric strain is
  // a target-blind preference among those exact actions, never an admission
  // rule and never a source of new coordinates.
  const evaluated = frontierCandidates.map((candidate) => {
    const evaluation = evaluateCandidate(candidate);
    const dynamicPriority = dynamicCandidatePriority(candidate);
    const referenceGain = candidateReferenceGain(candidate, audit);
    const baseScore = dynamicPriority + 2.5 * referenceGain;
    const score = baseScore
        - activeGeometricStrainWeight() * effectiveGeometricStrain(evaluation).total
        + evaluation.externalCalibration.weight * evaluation.externalCalibration.score
        - activeCompositionBalanceWeight() * evaluation.compositionBalance.scaledDelta
        + activeSolutePartitionWeight() * evaluation.solutePartition.score
        - activeFormalChargeWeight() * evaluation.formalChargeBalance.scaledDelta
        + activeChargeGeometryWeight() * evaluation.chargeGeometry.score
        + activeChargeMomentWeight() * evaluation.chargeMoment.score
        + activeIonicPairWeight() * evaluation.ionicPair.score
        + activeBondValenceWeight() * evaluation.bondValence.score
        - activeSurfaceCompletionWeight() * evaluation.surfaceCompletion.scaledDelta
        + activeGrowthDrivingWeight() * evaluation.bulkSurfaceDriving.score
        + activeAttachmentTopologyWeight() * evaluation.attachmentTopology.score
        + activeHabitAnisotropyWeight() * evaluation.habitAnisotropy.score
        + activeDefectPrecursorWeight() * evaluation.defectPrecursors.score
        + activeCoherencyMemoryWeight() * evaluation.coherencyMemory.score
        + activeFrontMorphologyWeight() * evaluation.frontMorphology.score
        + activeCapillaryGeometryWeight() * evaluation.capillaryGeometry.score
        + activeEpitaxyWeight() * evaluation.epitaxyRegistry.score
        + activeExternalDriveWeight() * evaluation.externalDrive.alignment
        + activeThermalFieldWeight() * evaluation.thermalField.score
        + activeRobustnessWeight() * evaluation.constraintRobustness.score
        + activeMicrostructureCouplingWeight() * evaluation.microstructureCoupling.score
        + activeLoopClosureWeight() * evaluation.loopClosure.score
        + activeArrivalPathWeight() * evaluation.arrivalPath.score
        + activeFeedExposureWeight() * evaluation.feedExposure.score;
    const explorationOffset = geometricExplorationOffset(candidate);
    candidate.explorationOffset = explorationOffset;
    return { candidate, evaluation, sites: evaluation.sites, dynamicPriority, referenceGain,
      referenceGuided: !reconstructionCertified, baseScore, score,
      explorationOffset, selectionScore: score + explorationOffset };
  });
  capturePolicyComparison(evaluated);
  const ranked = evaluated.sort((first, second) => second.selectionScore - first.selectionScore
    || first.candidate.key.localeCompare(second.candidate.key));
  if (overlapGrammar.molecular && !reconstructionCertified) {
    const ordered = ranked.slice().sort((first, second) => first.candidate.rule.replayOrder - second.candidate.rule.replayOrder);
    for (const entry of ordered) {
      if (entry.evaluation.accepted || rejectionIsOrderInvariant(entry.candidate, entry.evaluation)) {
        return [entry];
      }
    }
    return [];
  }
  if (growthScheduling === "serial") {
    const selected = ranked.find((entry) => entry.evaluation.accepted
      || rejectionIsOrderInvariant(entry.candidate, entry.evaluation));
    return selected ? [selected] : [];
  }
  const acceptedBatch = [];
  const rejectedBatch = [];
  for (const entry of ranked) {
    const { candidate, evaluation } = entry;
    if (evaluation.accepted) {
      if (!acceptedBatch.every((other) => sitesCanCommute(entry.sites, other.sites))) continue;
      const trial = [...acceptedBatch, entry];
      const trialFresh = uniqueFreshSites(trial.flatMap((trialEntry) => trialEntry.evaluation.fresh));
      if (!feedstockSupplyForFreshSites(trialFresh).admitted) continue;
      const trialProjection = constraintProjectionForFreshSites(trialFresh);
      if (coordinationOverflowsForFreshSites(trialFresh, trialProjection).length
        || angularViolationsForFreshSites(trialFresh, trialProjection).length) continue;
      if (!batchRetainsNovelSites(trial)) continue;
      acceptedBatch.push(entry);
      continue;
    }
    // "Insufficient shared support" can become valid after another placement,
    // so it is deferred rather than flashed red. The failures retained here
    // remain failures after any permutation of the accepted batch.
    if (!rejectionIsOrderInvariant(candidate, evaluation)) continue;
    if (![...acceptedBatch, ...rejectedBatch].every((other) => sitesCanCommute(entry.sites, other.sites))) continue;
    rejectedBatch.push(entry);
  }
  return [...acceptedBatch, ...rejectedBatch];
}

function refineCandidateTranslation(candidate) {
  const corrections = [];
  candidateSites(candidate).forEach((site) => {
    const match = nearbyAtoms(site.p, .34).filter((atom) => atom.species === site.species)
      .sort((first, second) => first.p.distanceToSquared(site.p) - second.p.distanceToSquared(site.p))[0];
    if (match) corrections.push(match.p.clone().sub(site.p));
  });
  if (corrections.length < 2) return;
  const correction = corrections.reduce((sum, value) => sum.add(value), new THREE.Vector3()).multiplyScalar(1 / corrections.length);
  if (correction.length() <= .18) candidate.position.add(correction);
}

function evaluateCandidate(candidate, {
  refinePose = true,
  recordWork = true,
  targetAware = true,
  enforceMarking = true,
} = {}) {
  if (refinePose) refineCandidateTranslation(candidate);
  const rawSites = candidateSites(candidate);
  const reconstructing = targetAware && !reconstructionCertified && replayIndex < referenceCount();
  const canonical = reconstructing ? canonicalKnownSites(rawSites) : { sites: rawSites, failures: 0, duplicateSites: 0 };
  const sites = canonical.sites;
  const audit = reconstructing ? referenceCoverageAudit() : null;
  const merged = [];
  const fresh = [];
  let conflicts = 0;
  let boundaryFailures = 0;
  sites.forEach((site) => {
    if (reconstructing) {
      if (audit.matchedMask[site.referenceIndex]) {
        const atom = atoms.find((candidateAtom) => candidateAtom.referenceIndex === site.referenceIndex)
          || nearbyAtoms(site.p, MERGE_TOLERANCE).find((candidateAtom) => candidateAtom.species === site.species);
        if (atom) merged.push({ site, atom });
      } else fresh.push(site);
      return;
    }
    const neighborhood = nearbyAtoms(site.p, coloredDistanceEnvelopes?.maximumExclusion || COLLISION_TOLERANCE)
      .sort((first, second) => first.p.distanceToSquared(site.p) - second.p.distanceToSquared(site.p));
    const same = neighborhood.find((atom) => atom.species === site.species && atom.p.distanceTo(site.p) <= MERGE_TOLERANCE);
    if (same) merged.push({ site, atom: same });
    else if (neighborhood.some((atom) => atom.p.distanceTo(site.p) < coloredPairExclusion(site.species, atom.species))) conflicts++;
    else if (!insideGrowthDomain(site.p)) boundaryFailures++;
    else fresh.push(site);
  });
  const markingAccepted = !enforceMarking || policySelect.value !== "marked" || candidate.markingAccepted;
  const knownFailures = reconstructing ? canonical.failures : 0;
  const markingFallback = reconstructing && knownFailures === 0 && !markingAccepted;
  const constraintProjection = constraintProjectionForFreshSites(fresh, { recordWork });
  const coordinationOverflows = reconstructing ? [] : coordinationOverflowsForFreshSites(fresh, constraintProjection);
  const angularViolations = reconstructing ? [] : angularViolationsForFreshSites(fresh, constraintProjection);
  const geometricStrain = geometricStrainForFreshSites(fresh, constraintProjection);
  const externalCalibration = externalCalibrationForFreshSites(fresh, constraintProjection);
  const affineLoadedGeometricStrain = affineLoadedGeometricStrainForFreshSites(fresh, constraintProjection);
  const surfaceCompletion = surfaceCompletionForFreshSites(fresh, constraintProjection);
  const bulkSurfaceDriving = bulkSurfaceDrivingForCandidate(fresh, surfaceCompletion, { recordWork });
  const attachmentTopology = attachmentTopologyForCandidate(candidate, fresh, { recordWork });
  const habitAnisotropy = habitAnisotropyForCandidate(candidate, { recordWork });
  const frontMorphology = frontMorphologyForCandidate(candidate, { recordWork });
  const capillaryGeometry = capillaryGeometryForFreshSites(fresh, { recordWork });
  const epitaxyRegistry = epitaxyRegistryForFreshSites(fresh, { recordWork });
  const compositionBalance = compositionBalanceForFreshSites(fresh);
  const feedstockSupply = feedstockSupplyForFreshSites(fresh);
  const formalChargeBalance = formalChargeBalanceForFreshSites(fresh);
  const chargeGeometry = chargeGeometryForFreshSites(fresh, { recordWork });
  const chargeMoment = chargeMomentForFreshSites(fresh, { recordWork });
  const ionicPair = ionicPairForFreshSites(fresh, { recordWork });
  const bondValence = bondValenceForFreshSites(fresh, { recordWork });
  const externalDrive = externalDriveForCandidate(candidate);
  const thermalField = reducedThermalFieldForCandidate(candidate, { recordWork });
  const solutePartition = solutePartitionForFreshSites(fresh, thermalField, capillaryGeometry, { recordWork });
  const constraintRobustness = constraintRobustnessForCandidate(fresh, merged);
  const interfaceAccommodation = interfaceAccommodationForCandidate(candidate, { fresh, merged });
  const microstructureCoupling = microstructureCouplingForCandidate(candidate,
    { fresh, merged, interfaceAccommodation });
  const loopClosure = mesoscopicLoopClosureForCandidate(candidate);
  const defectPrecursors = defectPrecursorsForAction({ geometricStrain, surfaceCompletion, compositionBalance, loopClosure }, { recordWork });
  const coherencyMemory = coherencyMemoryForCandidate(candidate, { geometricStrain, merged }, { recordWork });
  const arrivalPath = geometricArrivalPathForCandidate(candidate, fresh);
  const feedExposure = feedstockExposureForFreshSites(fresh, { recordWork });
  const accepted = conflicts === 0 && boundaryFailures === 0 && merged.length >= 2
    && fresh.length > 0 && knownFailures === 0 && coordinationOverflows.length === 0
    && angularViolations.length === 0 && feedstockSupply.admitted && (markingAccepted || markingFallback);
  return { accepted, sites, merged, fresh, conflicts, boundaryFailures, knownFailures, markingAccepted, markingFallback,
    coordinationOverflows, angularViolations, geometricStrain, externalCalibration, affineLoadedGeometricStrain,
    surfaceCompletion, bulkSurfaceDriving, attachmentTopology, habitAnisotropy, frontMorphology, capillaryGeometry, epitaxyRegistry, compositionBalance, feedstockSupply, formalChargeBalance, chargeGeometry, chargeMoment, ionicPair, bondValence,
    externalDrive, thermalField, solutePartition, constraintRobustness, interfaceAccommodation,
    microstructureCoupling, loopClosure, defectPrecursors, coherencyMemory, arrivalPath, feedExposure,
    duplicateSites: canonical.duplicateSites,
    freshReferenceIndices: fresh.map((site) => site.referenceIndex).filter(Number.isInteger),
    reason: conflicts ? `${conflicts} hard-core/species conflicts` : boundaryFailures ? "outside confinement" : knownFailures ? `${knownFailures} sites outside known configuration` : coordinationOverflows.length ? `${coordinationOverflows.length} colored coordination capacities exceeded` : angularViolations.length ? `${angularViolations.length} colored angular envelopes violated` : !feedstockSupply.admitted ? `feedstock exhausted: ${feedstockSupply.limitingSpecies.join(" / ")}` : merged.length < 2 ? "insufficient shared support" : fresh.length === 0 ? "duplicate covering" : !markingAccepted ? "marking mismatch" : "compatible overlap" };
}

function referenceCoverageCount() {
  return referenceCoverageAudit().matched;
}

function iceAnchorScenePoint(point) {
  const scale = .92 / currentMaterial().spacingA;
  return new THREE.Vector3(...point).sub(new THREE.Vector3(...iceAnchorTrace.boundaryCenter)).multiplyScalar(scale);
}

function initializeIceAnchorSearch() {
  iceAnchorTrace = scenarioSelect.value === "iceVI"
    ? executeFrozenIceViAnchorTrace(ICE_VI_ANCHOR_TRACE_ARTIFACT)
    : executeIceMolecularAnchorGrowth(ICE_MOLECULAR_PORT_ARTIFACT, scenarioSelect.value);
  if (!iceAnchorTrace.exactBackendCountParity || iceAnchorTrace.targetUsed) {
    throw new Error("Frozen browser ice continuation diverged from its sealed backend certificate");
  }
  iceAnchorWaveIndex = 0;
  atoms = [];
  placedClusters = [];
  frontierCandidates = [];
  reconstructionCertified = true;
  iceAnchorTrace.seedSites.forEach(([species, point], index) => {
    const atom = addAtom(iceAnchorScenePoint(point), species, "ice-anchor", null, true);
    atom.anchorDomain = true;
    atom.clusterIds = [index + 1];
    indexAtom(atom);
  });
  growthStartAtomCount = atoms.length;
  replayIndex = 0;
  stackHistory = [{ type: "accept", depth: 0,
    action: `${iceAnchorTrace.seedAnchors} observed O anchors`, family: "sealed disjoint seed" }];
}

function growthSeedSites(occurrenceIndex) {
  const occurrence = overlapGrammar.occurrences[occurrenceIndex];
  if (overlapGrammar.coverBased || overlapGrammar.molecular) return occurrence.sites;
  const inverseFrame = occurrence.rotation.clone().invert();
  const sites = [{ local: new THREE.Vector3(), species: referenceAtoms[occurrenceIndex].species, center: true }];
  learnedClusters.environments[occurrenceIndex].shell
    .filter((neighbor) => neighbor.r <= motifShellCutoff())
    .forEach((neighbor) => sites.push({
      local: neighbor.vector.clone().multiplyScalar(referenceSpacing / referenceSpacingA).applyQuaternion(inverseFrame),
      species: neighbor.atom.species, center: false,
    }));
  return sites;
}

function growthSeedType(occurrenceIndex) {
  const occurrence = overlapGrammar.occurrences[occurrenceIndex];
  return overlapGrammar.coverBased || overlapGrammar.molecular
    ? occurrence.type : learnedClusters.labels[occurrenceIndex];
}

const NUCLEATION_SITE_LABELS = Object.freeze({
  replay: "replay anchor", interior: "homogeneous interior", surface: "exposed support",
  gap: "gap / residual adjacent", interface: "pose interface", dispersed: "dispersed observed sites",
});

function nucleationSiteLabel() {
  return NUCLEATION_SITE_LABELS[nucleationSiteMode] || NUCLEATION_SITE_LABELS.replay;
}

function nucleationSiteEvidenceLabel(entry) {
  if (!entry) return "unavailable";
  if (nucleationSiteMode === "interior" || nucleationSiteMode === "surface") {
    const marginA = entry.boundaryMargin * referenceSpacingA / Math.max(referenceSpacing, 1e-12);
    return `${marginA.toFixed(2)} Å boundary margin`;
  }
  if (nucleationSiteMode === "gap") return `${entry.gapEvidence} gap / residual roles`;
  if (nucleationSiteMode === "interface") return `${entry.interfaceEvidence} pose-interface roles`;
  if (nucleationSiteMode === "dispersed") {
    const distanceA = entry.centroidDistance * referenceSpacingA / Math.max(referenceSpacing, 1e-12);
    return `${distanceA.toFixed(2)} Å from occurrence centroid`;
  }
  return entry.index === overlapGrammar.replaySeedIndex ? "frozen replay occurrence" : "fitted occurrence";
}

function renderNucleationLandscapeInspector() {
  const visible = pipelineStage === 4 && !iceAnchorTrace && nucleationSiteLandscape.length > 0;
  nucleationLandscapeInspector.hidden = !visible;
  if (!visible) return;
  const selected = nucleationSiteLandscape.filter((entry) => entry.selected);
  nucleationLandscapeState.textContent = `${nucleationSiteLabel()} · ${selected.length} selected`;
  const tiles = [
    ["fitted candidates", nucleationSiteLandscape.length],
    ["initialized seeds", selected.length],
    ["evidence", nucleationSelectionAudit?.evidenceAvailable ? "available" : "fallback"],
  ];
  nucleationLandscapeSummary.replaceChildren(...tiles.map(([label, value]) => {
    const tile = document.createElement("span");
    tile.innerHTML = `<small>${label}</small><strong>${value}</strong>`;
    return tile;
  }));
  const displayed = [...selected, ...nucleationSiteLandscape.filter((entry) => !entry.selected).slice(0, 4)]
    .filter((entry, index, array) => array.findIndex((candidate) => candidate.index === entry.index) === index)
    .slice(0, 6);
  nucleationLandscapeCandidates.replaceChildren(...displayed.map((entry) => {
    const card = document.createElement("article");
    card.classList.toggle("selected", entry.selected);
    card.innerHTML = `<small>${entry.selected ? "initialized seed" : `rank ${entry.rank}`}</small><strong>C${growthSeedType(entry.index) + 1} · ${growthSeedSites(entry.index).length} sites</strong><em>${nucleationSiteEvidenceLabel(entry)}</em>`;
    return card;
  }));
}

function observedGrowthSeedIndices() {
  const requested = Math.max(1, requestedGrowthNuclei);
  const replaySeed = overlapGrammar.replaySeedIndex;
  const eligible = overlapGrammar.occurrences.map((occurrence, index) => ({ occurrence, index }))
    .filter(({ occurrence, index }) => occurrence?.position && growthSeedSites(index).length >= 2)
    .sort((a, b) => a.index - b.index);
  const referenceSupports = new Map(eligible.map(({ occurrence, index }) => [index, new Set(canonicalKnownSites(
    growthSeedSites(index).map((site) => ({ ...site,
      p: site.local.clone().applyQuaternion(occurrence.rotation).add(occurrence.position) }))).sites
    .map((site) => site.referenceIndex))]));
  const roleByIndex = new Map((microstructureEvidence?.siteRoles || []).map((role) => [role.index, role]));
  const centroid = eligible.reduce((sum, entry) => sum.add(entry.occurrence.position), new THREE.Vector3())
    .multiplyScalar(1 / Math.max(1, eligible.length));
  const features = eligible.map((entry) => {
    const support = [...(referenceSupports.get(entry.index) || [])];
    const roles = support.map((index) => roleByIndex.get(index)).filter(Boolean);
    return { ...entry,
      boundaryMargin: growthEnvironmentSignedMargin(confinementSelect.value, entry.occurrence.position, growthDomainScale),
      gapEvidence: roles.filter((role) => role.gapBoundary || role.literalTerminal).length,
      interfaceEvidence: roles.filter((role) => role.poseInterface).length,
      centroidDistance: entry.occurrence.position.distanceTo(centroid),
    };
  });
  const ranked = features.slice().sort((a, b) => {
    if (nucleationSiteMode === "interior") return b.boundaryMargin - a.boundaryMargin || a.index - b.index;
    if (nucleationSiteMode === "surface") return a.boundaryMargin - b.boundaryMargin || a.index - b.index;
    if (nucleationSiteMode === "gap") return b.gapEvidence - a.gapEvidence || a.index - b.index;
    if (nucleationSiteMode === "interface") return b.interfaceEvidence - a.interfaceEvidence || a.index - b.index;
    if (nucleationSiteMode === "dispersed") return b.centroidDistance - a.centroidDistance || a.index - b.index;
    return (a.index === replaySeed ? -1 : 0) - (b.index === replaySeed ? -1 : 0) || a.index - b.index;
  });
  const evidenceAvailable = nucleationSiteMode !== "gap" && nucleationSiteMode !== "interface"
    || ranked.some((entry) => nucleationSiteMode === "gap" ? entry.gapEvidence > 0 : entry.interfaceEvidence > 0);
  let first = evidenceAvailable && ranked.length ? ranked[0].index : replaySeed;
  let pool = eligible;
  if (requested > 1) {
    const byType = new Map();
    eligible.forEach((entry) => {
      const type = growthSeedType(entry.index);
      const group = byType.get(type) || [];
      group.push(entry); byType.set(type, group);
    });
    const recurring = [...byType.entries()].filter(([, group]) => group.length >= requested)
      .sort((a, b) => b[1].length - a[1].length || a[0] - b[0])[0];
    if (recurring) {
      pool = recurring[1];
      const poolIndices = new Set(pool.map((entry) => entry.index));
      first = ranked.find((entry) => poolIndices.has(entry.index))?.index ?? pool[0].index;
    }
  }
  const selected = [first];
  while (selected.length < requested) {
    const occupied = new Set(selected.flatMap((index) => [...(referenceSupports.get(index) || [])]));
    const next = pool.filter(({ index }) => !selected.includes(index)
        && [...(referenceSupports.get(index) || [])].every((referenceIndex) => !occupied.has(referenceIndex)))
      .map(({ occurrence, index }) => ({ index, minimumSeparation: Math.min(...selected.map((chosen) =>
        occurrence.position.distanceTo(overlapGrammar.occurrences[chosen].position))) }))
      .sort((a, b) => b.minimumSeparation - a.minimumSeparation || a.index - b.index)[0];
    if (!next || next.minimumSeparation < referenceSpacing * 1.5) break;
    selected.push(next.index);
  }
  const selectedFeatures = selected.map((index) => features.find((entry) => entry.index === index)).filter(Boolean);
  nucleationSiteLandscape = ranked.map((entry, rank) => ({ ...entry, rank: rank + 1,
    selected: selected.includes(entry.index), position: entry.occurrence.position.clone() }));
  nucleationSelectionAudit = {
    mode: nucleationSiteMode, label: nucleationSiteLabel(), requested, selected: selected.length,
    eligibleObservedOccurrences: eligible.length, evidenceAvailable,
    fallback: evidenceAvailable ? null : "requested local role absent; replay anchor retained",
    selectedBoundaryMarginsSceneUnits: selectedFeatures.map((entry) => receiptRound(entry.boundaryMargin)),
    selectedGapResidualRoleCounts: selectedFeatures.map((entry) => entry.gapEvidence),
    selectedPoseInterfaceRoleCounts: selectedFeatures.map((entry) => entry.interfaceEvidence),
    landscapeVisualization: { rankedFittedOccurrences: ranked.length,
      displayedCandidateHalos: Math.min(24, Math.max(0, ranked.length - selected.length)),
      displayedSelectedHalos: selected.length, coordinatesEmbeddedInReceipt: false },
    selectedOccurrencesWereFitted: true, properObservedPosesPreserved: true,
    candidateGeometryChanged: false, heldoutTargetUsed: false,
    nucleationBarrierInferred: false, nucleationRateInferred: false, criticalNucleusSizeInferred: false,
  };
  return selected;
}

function growthNucleusOccurrence(placement) {
  const sites = growthSeedSites(placement.occurrenceIndex);
  return {
    species: sites.map((site) => site.species),
    positions: sites.map((site) => site.local.clone().applyQuaternion(placement.rotation)
      .add(placement.position).toArray()),
  };
}

function growthNucleusPairs() {
  const nuclei = placedClusters.filter((placement) => placement.seedNucleus)
    .sort((a, b) => a.nucleusId - b.nucleusId);
  const pairs = [];
  for (let first = 0; first < nuclei.length; first++) for (let second = first + 1; second < nuclei.length; second++) {
    const a = nuclei[first]; const b = nuclei[second];
    const misorientation = symmetryReducedMisorientation(growthNucleusOccurrence(a), growthNucleusOccurrence(b), {
      metricToleranceFraction: effectiveClusterMetricTolerance(),
    });
    const atomsA = atoms.filter((atom) => atom.nucleusIds?.includes(a.nucleusId));
    const atomsB = atoms.filter((atom) => atom.nucleusIds?.includes(b.nucleusId));
    const shared = atoms.filter((atom) => atom.nucleusIds?.includes(a.nucleusId)
      && atom.nucleusIds.includes(b.nucleusId));
    const scaleToAngstrom = referenceSpacingA / Math.max(referenceSpacing, 1e-12);
    const interfaceGeometry = interfaceGeometryAudit({
      positions: atoms.map((atom) => atom.p.toArray()), species: atoms.map((atom) => atom.species),
      memberships: atoms.map((atom) => atom.nucleusIds || []),
      firstNucleusId: a.nucleusId, secondNucleusId: b.nucleusId,
      firstCenter: a.position.toArray(), secondCenter: b.position.toArray(), lengthScale: scaleToAngstrom,
      contactCutoff: (firstSpecies, secondSpecies) =>
        coordinationEnvelopeFor(coloredCoordinationEnvelopes, firstSpecies, secondSpecies)?.contactCutoff || null,
    });
    const interfaceCoordination = coordinationDeficitForIndices(atoms, interfaceGeometry.sharedIndices);
    const interfaceShape = covarianceMorphology(shared, scaleToAngstrom);
    interfaceGeometry.coordinationDeficit = Number.isFinite(interfaceCoordination.mean)
      ? receiptRound(interfaceCoordination.mean) : null;
    interfaceGeometry.coordinationTerms = interfaceCoordination.terms;
    interfaceGeometry.covariancePhenotype = interfaceShape.phenotype;
    interfaceGeometry.intrinsicDimension = interfaceShape.intrinsicDimension;
    interfaceGeometry.relativeShapeAnisotropy = receiptRound(interfaceShape.relativeShapeAnisotropy);
    pairs.push({ key: `${a.nucleusId}:${b.nucleusId}`, first: a, second: b, misorientation,
      centerSeparationAngstrom: a.position.distanceTo(b.position) * referenceSpacingA / referenceSpacing,
      sharedSites: shared.length, firstSites: atomsA.length, secondSites: atomsB.length,
      sharedSiteFraction: shared.length / Math.max(1, Math.min(atomsA.length, atomsB.length)),
      interfaceGeometry, sameClusterType: a.type === b.type, targetUsed: false });
  }
  return pairs;
}

function renderNucleusInterfaceInspector() {
  const pairs = pipelineStage === 4 ? growthNucleusPairs() : [];
  nucleusInterfaceInspector.hidden = pairs.length === 0;
  if (!pairs.length) return;
  if (!pairs.some((pair) => pair.key === selectedNucleusPairKey)) selectedNucleusPairKey = pairs[0].key;
  const selected = pairs.find((pair) => pair.key === selectedNucleusPairKey) || pairs[0];
  nucleusInterfaceState.textContent = selected.sharedSites
    ? `${selected.sharedSites} registered sites` : "domains separated";
  nucleusPairButtons.replaceChildren();
  pairs.forEach((pair) => {
    const button = document.createElement("button"); button.type = "button";
    button.classList.toggle("active", pair.key === selected.key);
    button.setAttribute("aria-pressed", String(pair.key === selected.key));
    button.textContent = `N${pair.first.nucleusId} ↔ N${pair.second.nucleusId}`;
    button.addEventListener("click", () => {
      selectedNucleusPairKey = pair.key;
      renderNucleusInterfaceInspector();
      rebuildWorld();
    });
    nucleusPairButtons.append(button);
  });
  nucleusPairDetail.replaceChildren();
  const angle = selected.misorientation.comparable
    ? `${selected.misorientation.angleDegrees.toFixed(2)}°` : "not comparable";
  const geometry = selected.interfaceGeometry;
  const length = (value) => Number.isFinite(value) ? `${value.toFixed(2)} Å` : "unresolved";
  const chemistry = Object.entries(geometry.chemistry).map(([symbol, count]) => `${symbol}${count}`).join(" · ") || "none";
  [
    ["proper misorientation", angle, selected.misorientation.comparable
      ? `${selected.misorientation.properGaugePairs} symmetry-gauge pairs minimized` : selected.misorientation.reason],
    ["seed separation", `${selected.centerSeparationAngstrom.toFixed(2)} Å`, "observed occurrence centers"],
    ["shared-site registry", `${selected.sharedSites} sites · ${(selected.sharedSiteFraction * 100).toFixed(1)}%`, `${selected.firstSites} / ${selected.secondSites} lineage sites`],
    ["registry topology", geometry.registryTopology, `${geometry.componentCount ?? "—"} colored-contact component${geometry.componentCount === 1 ? "" : "s"} · ${chemistry}`],
    ["axial contact thickness", length(geometry.axialThicknessRms), `RMS along observed seed-center axis · ${length(geometry.axialSpan)} span · centroid ${length(geometry.axialCentroidOffset)} from midpoint`],
    ["tangential spread", length(geometry.tangentialRadiusRms), `${length(geometry.tangentialRadiusMaximum)} maximum radius`],
    ["interface exposure", Number.isFinite(geometry.coordinationDeficit)
      ? `${(100 * geometry.coordinationDeficit).toFixed(1)}%` : "unresolved",
    `${geometry.coordinationTerms} colored coordination terms · ${geometry.covariancePhenotype}`],
    ["claim boundary", "finite registered contact zone", "no boundary area, grain identity, energy, mobility, or time"],
  ].forEach(([label, value, detail]) => {
    const row = document.createElement("div"); const small = document.createElement("small");
    const strong = document.createElement("strong"); const span = document.createElement("span");
    small.textContent = label; strong.textContent = value; span.textContent = detail;
    row.append(small, strong, span); nucleusPairDetail.append(row);
  });
  nucleusInterfaceProfile.replaceChildren();
  const profileMaximum = Math.max(1, ...geometry.profile);
  geometry.profile.forEach((count, index) => {
    const bar = document.createElement("span"); const fill = document.createElement("i");
    fill.style.height = `${100 * count / profileMaximum}%`; bar.append(fill);
    bar.title = `axial bin ${index + 1}: ${count} shared site${count === 1 ? "" : "s"}`;
    nucleusInterfaceProfile.append(bar);
  });
  nucleusInterfaceProfile.setAttribute("aria-label",
    `Seven-bin axial shared-site profile; ${geometry.sharedSiteCount} total registered sites`);
  renderNucleusInterfaceEvolution(selected.key);
}

function structuralInterfaceSnapshot() {
  const pairs = growthNucleusPairs().map((pair) => ({
    key: pair.key, nuclei: [pair.first.nucleusId, pair.second.nucleusId],
    misorientationDegrees: pair.misorientation.comparable
      ? receiptRound(pair.misorientation.angleDegrees) : null,
    properGaugePairs: pair.misorientation.properGaugePairs || 0,
    sharedSites: pair.sharedSites, sharedSiteFraction: receiptRound(pair.sharedSiteFraction),
    registryTopology: pair.interfaceGeometry.registryTopology,
    componentCount: pair.interfaceGeometry.componentCount,
    axialThicknessRms: pair.interfaceGeometry.axialThicknessRms,
    axialSpan: pair.interfaceGeometry.axialSpan,
    tangentialRadiusRms: pair.interfaceGeometry.tangentialRadiusRms,
    coordinationDeficit: pair.interfaceGeometry.coordinationDeficit,
    chemistry: pair.interfaceGeometry.chemistry,
    profile: [...pair.interfaceGeometry.profile], targetUsed: false,
  })).sort((first, second) => second.sharedSites - first.sharedSites || first.key.localeCompare(second.key));
  return { pairCount: pairs.length, coalescedPairCount: pairs.filter((pair) => pair.sharedSites > 0).length,
    totalSharedSites: pairs.reduce((sum, pair) => sum + pair.sharedSites, 0), pairs,
    primaryPair: pairs[0] || null, alignment: "structural leap index",
    coordinateFrameUsed: false, targetUsed: false, physicalTimeModeled: false,
    grainIdentityInferred: false, interfacialEnergyInferred: false, mobilityInferred: false };
}

function interfaceEvolutionForPair(pairKey) {
  const states = [];
  if (leapHistory[0]?.before?.interfaces) states.push({
    step: Math.max(0, leapHistory[0].index - 1),
    pair: leapHistory[0].before.interfaces.pairs.find((pair) => pair.key === pairKey) || null,
  });
  leapHistory.forEach((leap) => {
    if (leap.after?.interfaces) states.push({ step: leap.index,
      pair: leap.after.interfaces.pairs.find((pair) => pair.key === pairKey) || null });
  });
  return states;
}

function renderNucleusInterfaceEvolution(pairKey) {
  if (!nucleusInterfaceEvolution || !nucleusInterfaceEvolutionState) return;
  const states = interfaceEvolutionForPair(pairKey);
  nucleusInterfaceEvolution.replaceChildren();
  nucleusInterfaceEvolutionState.textContent = states.length
    ? `${states.length} certified state${states.length === 1 ? "" : "s"}` : "seed state";
  const maxima = {
    sites: Math.max(1, ...states.map((state) => state.pair?.sharedSites || 0)),
    components: Math.max(1, ...states.map((state) => state.pair?.componentCount || 0)),
    thickness: Math.max(1e-9, ...states.map((state) => state.pair?.axialThicknessRms || 0)),
  };
  states.slice(-12).forEach((state) => {
    const column = document.createElement("div"); const label = document.createElement("small");
    const tracks = document.createElement("span"); const pair = state.pair;
    label.textContent = `L${state.step}`;
    [["sites", pair?.sharedSites || 0, maxima.sites], ["patches", pair?.componentCount || 0, maxima.components],
      ["thickness", pair?.axialThicknessRms || 0, maxima.thickness],
      ["exposure", pair?.coordinationDeficit || 0, 1]].forEach(([name, value, maximum]) => {
      const track = document.createElement("i"); const fill = document.createElement("b");
      track.dataset.metric = name; fill.style.width = `${100 * value / maximum}%`; track.append(fill); tracks.append(track);
    });
    column.title = `structural leap ${state.step}: ${pair?.sharedSites || 0} registered sites · ${pair?.componentCount || 0} patches · ${Number.isFinite(pair?.axialThicknessRms) ? `${pair.axialThicknessRms.toFixed(2)} Å thick` : "thickness unresolved"}`;
    column.append(label, tracks); nucleusInterfaceEvolution.append(column);
  });
}

